-- BUGÜN: Afyonkarahisar'ın bilinen tarih, müze ve doğa durakları.
insert into public.places
  (name, category, place_type, city, address, latitude, longitude, slug,
   short_description, long_description, source_url, external_source, external_id,
   verified, trust_score, is_active, content_review_status, tags)
select v.name, v.category, v.place_type, 'Afyonkarahisar', v.address, v.lat, v.lon, v.slug,
       v.short_description, v.long_description, v.source_url, 'curated_seed',
       'afyonkarahisar-' || v.slug, false, 80, true, 'source_backed', v.tags::jsonb
from (values
 ('Afyonkarahisar Kalesi','Tarih','Kale','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'afyonkarahisar-kalesi','Şehir merkezine hâkim volkanik kaya üzerindeki tarihî kale.','Afyonkarahisar’ın simgesi olan kale, dik kayalık zirvesi ve şehir manzarasıyla öne çıkar; çıkış için merdivenli ve eğimli güzergâh bulunur.','https://afyon.ktb.gov.tr/','["kale","tarih","manzara"]'),
 ('Afyon Ulu Camii','Tarih','Tarihî cami','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'afyon-ulu-camii','Selçuklu döneminden kalan ahşap direkli cami.','13. yüzyıla tarihlenen Ulu Camii, ahşap direkli ve tavanlı cami mimarisinin önemli örneklerindendir.','https://whc.unesco.org/','["cami","Selçuklu","mimari"]'),
 ('Afyonkarahisar Arkeoloji Müzesi','Müze','Arkeoloji müzesi','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'afyonkarahisar-arkeoloji-muzesi','Bölgenin tarih öncesi ve antik dönem eserlerini sergileyen müze.','Afyonkarahisar ve çevresindeki arkeolojik buluntularla bölgenin çok katmanlı tarihini tanıtır.','https://muze.gov.tr/','["müze","arkeoloji","tarih"]'),
 ('Zafer Müzesi','Müze','Millî mücadele müzesi','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'zafer-muzesi','Büyük Taarruz ve Millî Mücadele tarihiyle ilişkili müze.','Afyonkarahisar’ın Kurtuluş Savaşı tarihindeki yerini anlatan kent merkezindeki önemli kültür durağıdır.','https://afyon.ktb.gov.tr/','["müze","Millî Mücadele","tarih"]'),
 ('Sultan Divani Mevlevihanesi','Müze','Mevlevihane ve müze','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'sultan-divani-mevlevihanesi','Mevlevilik kültürünü ve tarihini tanıtan tarihî yapı.','Afyonkarahisar’ın tasavvuf ve kültür geçmişini yansıtan önemli tarihî mekânlardan biridir.','https://afyon.ktb.gov.tr/','["Mevlevilik","müze","tarih"]'),
 ('Taş Medrese','Tarih','Medrese','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'afyon-tas-medrese','Selçuklu döneminin taş işçiliğini yansıtan tarihî medrese.','Kent merkezindeki Selçuklu ve Osmanlı mirası rotasında görülebilecek mimari yapılardandır.','https://afyon.ktb.gov.tr/','["medrese","Selçuklu","mimari"]'),
 ('Frig Vadisi','Doğa','Kültürel peyzaj ve kaya anıtları','İhsaniye, Afyonkarahisar',39.1000::float8,30.6000::float8,'frig-vadisi-afyon','Kaya anıtları, oyma yapılar ve yürüyüş rotalarıyla geniş tarihî peyzaj.','Afyonkarahisar, Eskişehir ve Kütahya’ya yayılan Frig kültürel peyzajının Afyon bölümünde kaya yerleşimleri ve anıtlar görülebilir.','https://kulturportali.gov.tr/','["Frig","arkeoloji","doğa","yürüyüş"]'),
 ('Ayazini Ören Yeri','Tarih','Kaya yerleşimi','İhsaniye, Afyonkarahisar',39.1000::float8,30.6000::float8,'ayazini-oren-yeri','Kaya oyma kiliseleri, mezarları ve yerleşimleriyle tanınan köy.','Frig Vadisi içindeki Ayazini, farklı dönemlerden kaya oyma yapılarıyla kültür rotasının önemli duraklarındandır.','https://afyon.ktb.gov.tr/','["arkeoloji","kaya yerleşimi","Frig"]'),
 ('Emre Gölü','Doğa','Göl ve manzara','İhsaniye, Afyonkarahisar',39.1000::float8,30.6000::float8,'emre-golu','Frig Vadisi çevresinde göl ve kaya manzaraları.','Ayazini ve Frig Vadisi rotasıyla birlikte değerlendirilen açık hava ve fotoğraf noktasıdır.','https://afyon.ktb.gov.tr/','["göl","manzara","doğa"]'),
 ('Başkomutan Tarihi Millî Parkı','Tarih','Millî park ve savaş alanı','Merkez ve çevresi, Afyonkarahisar',38.7500::float8,30.5500::float8,'baskomutan-tarihi-milli-parki','Büyük Taarruz ve Başkomutanlık Meydan Muharebesi ile ilişkili tarihî alan.','Millî Mücadele’nin önemli safhalarının yaşandığı alanları ve anıtları kapsar; ziyaret güzergâhı için resmî yönlendirmeler izlenmelidir.','https://www.tarimorman.gov.tr/DKMP','["Millî Mücadele","tarih","anıt"]'),
 ('Kocatepe Anıtı ve Şehitliği','Tarih','Anıt ve şehitlik','Kocatepe, Afyonkarahisar',38.7000::float8,30.4000::float8,'kocatepe-aniti-sehitligi','Büyük Taarruz’un başlangıcıyla özdeşleşen tarihî anıt alanı.','Kocatepe, Millî Mücadele tarihini anmak ve öğrenmek için Türkiye’nin önemli tarihî ziyaret noktalarındandır.','https://www.tarimorman.gov.tr/DKMP','["Millî Mücadele","anıt","tarih"]'),
 ('İscehisar Peri Bacaları','Doğa','Jeolojik oluşum','İscehisar, Afyonkarahisar',38.8500::float8,30.7500::float8,'iscehisar-peri-bacalari','Volkanik tüflerin aşınmasıyla oluşmuş kaya şekilleri.','İscehisar çevresindeki jeolojik oluşumlar, Frigya bölgesinin doğal ve kültürel peyzajını tamamlar.','https://afyon.ktb.gov.tr/','["jeoloji","doğa","fotoğraf"]'),
 ('Gazlıgöl Termal Kaplıcaları','Termal','Kaplıca','İhsaniye, Afyonkarahisar',39.0500::float8,30.5500::float8,'gazligol-termal-kaplicalari','Afyonkarahisar’ın tanınmış termal turizm bölgelerinden.','Gazlıgöl çevresinde termal tesisler bulunur; tesislerin hizmet ve kullanım koşulları ziyaret öncesi kontrol edilmelidir.','https://afyon.ktb.gov.tr/','["termal","dinlenme","termal turizm"]'),
 ('Sandıklı Hüdai Kaplıcaları','Termal','Kaplıca','Sandıklı, Afyonkarahisar',38.4500::float8,30.2500::float8,'sandikli-hudai-kaplicalari','Sandıklı ilçesinin bilinen termal turizm noktası.','Hüdai çevresindeki kaplıca tesisleri bölgenin termal turizminde öne çıkar; güncel hizmet bilgileri işletmelerden kontrol edilmelidir.','https://afyon.ktb.gov.tr/','["termal","kaplıca","dinlenme"]'),
 ('Eber Gölü','Doğa','Göl ve sulak alan','Bolvadin, Afyonkarahisar',38.6000::float8,31.1500::float8,'eber-golu','Sazlıkları ve kuş yaşamıyla bilinen büyük sulak alan.','Eber Gölü doğal yaşam ve kuş gözlemi bakımından önem taşır; hassas sulak alan habitatına zarar vermeden ziyaret edilmelidir.','https://www.tarimorman.gov.tr/DKMP','["göl","sulak alan","kuş gözlemi"]'),
 ('Akdağ Tabiat Parkı','Doğa','Tabiat parkı','Sandıklı, Afyonkarahisar',38.4000::float8,30.0000::float8,'akdag-tabiat-parki-afyon','Orman, dağ manzarası ve açık hava etkinlikleriyle bilinen doğal alan.','Akdağ çevresi doğa yürüyüşü ve manzara gezileri için değerlendirilebilir; mevsim ve park erişim koşulları kontrol edilmelidir.','https://www.tarimorman.gov.tr/DKMP','["tabiat parkı","dağ","doğa"]'),
 ('Döğer Asar Kalesi','Tarih','Kaya kalesi','İhsaniye, Afyonkarahisar',39.1000::float8,30.4500::float8,'doger-asar-kalesi','Frig Vadisi çevresindeki kaya kalesi ve tarihî kalıntılar.','Döğer çevresindeki kaya oluşumları ve tarihî izler Frigya gezi rotasına eklenebilir; erişim ve zemin koşulları dikkatle değerlendirilmelidir.','https://afyon.ktb.gov.tr/','["kale","arkeoloji","Frig"]'),
 ('Ulu Camii ve Tarihî Merkez Yürüyüşü','Kültür','Tarihî kent rotası','Merkez, Afyonkarahisar',38.7560::float8,30.5380::float8,'afyon-tarihi-merkez-rotasi','Kent merkezindeki tarihî yapı ve çarşıları bir arada keşfetme rotası.','Ulu Camii, geleneksel çarşı dokusu ve yakın çevredeki tarihî yapılar yürüyerek keşfedilebilir.','https://afyon.ktb.gov.tr/','["şehir yürüyüşü","tarih","mimari"]')
) as v(name,category,place_type,address,lat,lon,slug,short_description,long_description,source_url,tags)
where not exists (
 select 1 from public.places p
 where lower(trim(p.city)) in ('afyonkarahisar','afyon')
   and (lower(trim(p.name))=lower(trim(v.name)) or p.slug=trim(v.slug))
);